package recovery_test

import (
	"antennarr/internal/catalog"
	"antennarr/internal/config"
	"antennarr/internal/recovery"
	"antennarr/internal/tuner"
	"bytes"
	"encoding/json"
	"io/fs"
	"net/http/httptest"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"testing"
	"time"
)

// Optional authentic fixtures generated by running the published images
// against synthetic appdata. No real account, key, or host configuration is used.
func TestPublishedBeta3UpgradeAndManualRestore(t *testing.T) {
	testPublishedUpgradeAndManualRestore(t, os.Getenv("ANTENNARR_UPGRADE_FIXTURE"), "beta3")
}

func TestPublishedV104UpgradeAndManualRestore(t *testing.T) {
	testPublishedUpgradeAndManualRestore(t, os.Getenv("ANTENNARR_V104_UPGRADE_FIXTURE"), "v1.0.4")
}

func testPublishedUpgradeAndManualRestore(t *testing.T, source, baseline string) {
	t.Helper()
	if source == "" {
		t.Skip("published-image fixture not supplied")
	}
	raw, e := os.ReadFile(filepath.Join(source, "expected.json"))
	if e != nil {
		t.Fatal(e)
	}
	expected := map[string]string{}
	if e = json.Unmarshal(raw, &expected); e != nil {
		t.Fatal(e)
	}
	if baseline == "v1.0.4" && (expected["baseline"] != baseline || expected["lineup_export"] == "") {
		t.Fatal("v1.0.4 fixture with saved channel definitions required")
	}
	channelCount := 143 // Older Beta 3 fixtures predate the explicit count.
	if value := expected["channel_count"]; value != "" {
		channelCount, e = strconv.Atoi(value)
		if e != nil || channelCount < 1 {
			t.Fatalf("invalid fixture channel count: %q", value)
		}
	}
	root := t.TempDir()
	e = filepath.WalkDir(filepath.Join(source, "data"), func(path string, d fs.DirEntry, e error) error {
		if e != nil {
			return e
		}
		rel, e := filepath.Rel(filepath.Join(source, "data"), path)
		if e != nil {
			return e
		}
		target := filepath.Join(root, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0700)
		}
		b, e := os.ReadFile(path)
		if e != nil {
			return e
		}
		return os.WriteFile(target, b, 0600)
	})
	if e != nil {
		t.Fatal(e)
	}
	c, e := config.Load(root)
	if e != nil {
		t.Fatal(e)
	}
	originalID := c.DeviceID
	if c.Settings.ReplenishWhilePlaying {
		t.Fatal("legacy configuration did not default to false")
	}
	s, e := catalog.Open(root)
	if e != nil {
		t.Fatal(e)
	}
	defer s.Close()
	if e = s.RefreshMatching(); e != nil {
		t.Fatal(e)
	}
	c.Settings.RosterTarget = 20
	c.Settings.ReplenishWhilePlaying = true
	if e = config.Save(root, c); e != nil {
		t.Fatal(e)
	}
	if e = s.EnableRosters(catalog.RosterPolicy{Target: 20, Preference: "stability", Race: 5}); e != nil {
		t.Fatal(e)
	}
	if e = s.ReconcileRosters(); e != nil {
		t.Fatal(e)
	}
	if e = s.EnsureRosterPass(time.Now().Unix()); e != nil {
		t.Fatal(e)
	}
	if e = s.DiscoveryFailedReason(31, false, "http_error", "catalogue", 503, true); e != nil {
		t.Fatal(e)
	}
	check := func(c config.Config, s *catalog.Store) {
		t.Helper()
		for table, want := range map[string]int{"accounts": 31, "roster": 30, "channels": channelCount} {
			var n int
			if e := s.DB.QueryRow("SELECT count(*) FROM " + table).Scan(&n); e != nil || n != want {
				t.Fatal(table, n, e)
			}
		}
		var kind, phase string
		var status int
		if e := s.DB.QueryRow("SELECT last_failure_kind,last_failure_phase,last_failure_status FROM accounts WHERE id=31").Scan(&kind, &phase, &status); e != nil || kind != "http_error" || phase != "catalogue" || status != 503 {
			t.Fatal(kind, phase, status, e)
		}
		var schema int
		s.DB.QueryRow("PRAGMA user_version").Scan(&schema)
		if schema != 8 {
			t.Fatal(schema)
		}
		if c.DeviceID != originalID || c.Settings.RosterTarget != 20 || !c.Settings.ReplenishWhilePlaying {
			t.Fatal("configuration changed")
		}
		if raw := expected["lineup_export"]; raw != "" {
			var want catalog.Lineup
			if e := json.Unmarshal([]byte(raw), &want); e != nil {
				t.Fatal(e)
			}
			got, e := s.ExportLineup()
			if e != nil || !reflect.DeepEqual(got, want) {
				t.Fatalf("saved channel definitions changed: %v", e)
			}
		}
		server := tuner.Server{Config: c, BaseURL: expected["base"], ChannelList: func() []config.Channel {
			chs, _ := s.Channels()
			out := []config.Channel{}
			for _, ch := range chs {
				if ch.Enabled {
					out = append(out, config.Channel{ID: ch.ID, Number: ch.Number, Name: ch.Name})
				}
			}
			return out
		}}
		for _, path := range []string{"/discover.json", "/lineup.json", "/device.xml"} {
			w := httptest.NewRecorder()
			server.Handler().ServeHTTP(w, httptest.NewRequest("GET", path, nil))
			if w.Code != 200 || w.Body.String() != expected[path] {
				t.Fatalf("Plex identity/lineup changed: %s", path)
			}
		}
	}
	check(c, s)
	var queueBefore string
	s.DB.QueryRow("SELECT group_concat(position,',') FROM (SELECT position FROM queue_positions ORDER BY kind,source_id)").Scan(&queueBefore)
	name, e := recovery.Create(root, expected["base"], s)
	if e != nil {
		t.Fatal(e)
	}
	archive, e := os.ReadFile(filepath.Join(root, "backups", name))
	if e != nil {
		t.Fatal(e)
	}
	restoredRoot := t.TempDir()
	if _, e = recovery.Stage(restoredRoot, bytes.NewReader(archive), int64(len(archive))); e != nil {
		t.Fatal(e)
	}
	if e = recovery.ApplyPending(restoredRoot); e != nil {
		t.Fatal(e)
	}
	after, e := catalog.Open(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	defer after.Close()
	saved, e := config.Load(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	check(saved, after)
	var queueAfter string
	after.DB.QueryRow("SELECT group_concat(position,',') FROM (SELECT position FROM queue_positions ORDER BY kind,source_id)").Scan(&queueAfter)
	if queueAfter != queueBefore {
		t.Fatal("random queue positions changed on restore")
	}
	beforePass, _ := s.CheckPassStatus()
	afterPass, _ := after.CheckPassStatus()
	if beforePass != afterPass {
		t.Fatal("saved pass progress changed")
	}
	oldLogin, e := config.OpenAdminLogin(root)
	if e != nil {
		t.Fatal(e)
	}
	newLogin, e := config.OpenAdminLogin(restoredRoot)
	if e != nil {
		t.Fatal(e)
	}
	if oldLogin.Current() != newLogin.Current() {
		t.Fatal("login changed")
	}
}
